<section class="comm-card"><h2>Payment request queue</h2><p class="muted">SMS and email requests are credit top-ups. Enabled Automation plans can be purchased online through MartPoint Pay or submitted with transfer evidence. New Central-billed payments and receipts are recorded in Next Admin; licence purchases remain request-only.</p><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Fleet / store</th><th>Module / purpose / transfer ref</th><th>Total / credits</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><a href="<?= base_url('communications_admin?account='.(int)$r['account_id']).$suffix; ?>"><?= $h($r['store_name']); ?></a><br><span class="mini"><?= $h($r['install_url']??'Central'); ?></span><br><?= $h($r['contact_email']); ?><?php foreach($sms_review['documents']??array() as $doc)if($doc['kind']==='receipt' && (int)$doc['reference_id']===(int)$r['id']): ?><br><a href="<?= base_url('communications_admin/document/'.(int)$doc['id']); ?>">Download payment receipt</a><?php endif; ?></td><td><?= $h(ucfirst($r['module_key']).' · '.$r['purpose']); ?><br><?= $h($r['billing_period']??'Credits'); ?><?php if(!empty($r['automation_plan_key'])): ?> · <?= $h($automation_admin['plans'][$r['automation_plan_key']]['name']??$r['automation_plan_key']); ?><?php endif; ?> · #<?= (int)$r['id']; ?><?php if($r['purpose']==='recharge'): ?><br><strong><?= $h('MP-COMM-'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)); ?></strong><?php endif; ?></td><td><?= $money(!empty($r['total_kobo'])?$r['total_kobo']:$r['amount_kobo']); ?><br><span class="mini"><?= $vatline($r); ?></span><br><?= $r['credit_units']?number_format($r['credit_units']).' credits':''; ?></td><td><span class="comm-badge <?= $r['status']==='approved'?'ok':'off'; ?>"><?= $h(str_replace('_',' ',$r['status'])); ?></span><br><span class="mini"><?= $h($r['note']??''); ?></span></td><td><?php if($r['purpose']==='subscription' && in_array($r['module_key'],array('sms','email'),true)): ?><?php if($r['status']==='requested'): $open('resolve',array('request_id'=>$r['id'],'account_id'=>$r['account_id'])); ?><input name="note" placeholder="Reason for closing this old request" minlength="5" maxlength="500" required><button class="btn secondary" name="approve" value="0">Close old request</button><?= form_close(); ?><?php else: ?><span class="notice error">Legacy subscription request. Do not activate. Check provider payment status; refund any payment already collected.</span><?php endif; ?><?php elseif($r['status']==='awaiting_payment'): $open('verify',array('request_id'=>$r['id'],'account_id'=>$r['account_id'])); ?><button class="btn secondary">Verify card payment</button><?= form_close(); ?><?php elseif(in_array($r['status'],array('requested','paid'),true)): $open('resolve',array('request_id'=>$r['id'],'account_id'=>$r['account_id'])); ?><input name="note" placeholder="Payment evidence / reason" minlength="5" maxlength="500" required><div class="row" style="margin-top:8px"><button class="btn" name="approve" value="1"><?= $r['purpose']==='subscription'?'Activate':'Confirm recharge'; ?></button><?php if($r['status']!=='paid'): ?><button class="btn secondary" name="approve" value="0">Reject</button><?php endif; ?></div><?= form_close(); ?><?php else: ?><?= $h($r['resolved_by']??'Payment gateway'); ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$requests): ?><p class="empty">Fleet requests will appear here.</p><?php endif; ?></section>
<section class="comm-card"><h2>Fleet-wide channel availability</h2><p class="muted">These switches apply to every existing and future store on a fleet. Store administrators cannot override a fleet-wide disable.</p><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Registered fleet</th><?php foreach($catalogue as $key=>$c): ?><th><?= $h($c['name']); ?></th><?php endforeach; ?></tr></thead><tbody><?php $fleetStates=array();foreach($fleet_states??array() as $state)$fleetStates[$state['fleet_id']][$state['module_key']]=$state;foreach($fleets as $f):if(!empty($selected_fleet) && $selected_fleet!=$f['id'])continue; ?><tr><td><a href="<?= base_url('communications_admin?fleet='.(int)$f['id']).$suffix; ?>"><?= $h($f['install_url']); ?></a></td><?php foreach($catalogue as $key=>$c): ?><td><?php if($c['development']): ?><span class="comm-badge off">Under development</span><?php else:$allowed=$fleetStates[$f['id']][$key]['allowed']??1;$open('fleet_allow',array('fleet_id'=>$f['id'],'module_key'=>$key)); ?><label class="row" style="margin:0"><input class="switch" type="checkbox" name="allowed" value="1" <?= $allowed?'checked':''; ?> onchange="this.form.submit()" aria-label="Allow <?= $h($c['name'].' for '.$f['install_url']); ?>"> <?= $allowed?'Allowed':'Disabled'; ?></label><?= form_close(); ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section>
<section class="comm-card"><h2>Fleet channel access</h2><p class="muted">SMS and Email are included channels; the switches control availability. Credits and balances remain separate for each fleet/store. Automation remains subscription-based.</p><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Fleet / store</th><?php foreach($catalogue as $key=>$c): ?><th><?= $h($c['name']); ?></th><?php endforeach; ?></tr></thead><tbody><?php $states=array();foreach($module_states as $state)$states[$state['account_id']][$state['module_key']]=$state;foreach($accounts as $a): ?><tr><td><a href="<?= base_url('communications_admin?account='.(int)$a['id']).$suffix; ?>"><b><?= $h($a['store_name']); ?></b></a><br><span class="mini"><?= $h($a['install_url']??'Central'); ?> · store #<?= (int)$a['store_id']; ?></span></td><?php foreach($catalogue as $key=>$c):$m=$states[$a['id']][$key]??array('allowed'=>1,'subscribed_until'=>null,'merchant_enabled'=>0);$included=in_array($key,array('sms','email'),true);$active=!$c['development'] && $c['enabled'] && $m['allowed'] && ($included || ($m['merchant_enabled'] && $m['subscribed_until'] && strtotime($m['subscribed_until'].' UTC')>time())); ?><td><?php if($c['development']): ?><span class="comm-badge off">Under development</span><?php else: $open('allow',array('account_id'=>$a['id'],'module_key'=>$key)); ?><label class="row" style="margin:0"><input type="checkbox" name="allowed" value="1" class="switch" <?= $m['allowed']?'checked':''; ?> onchange="this.form.submit()" aria-label="Allow <?= $h($c['name'].' for '.$a['store_name']); ?>"> Allowed</label><?= form_close(); ?><span class="comm-badge <?= $active?'ok':'off'; ?>"><?= $included?($active?'Included':'Unavailable'):($active?'Subscribed':'Inactive'); ?></span><?php if(!$included): ?><br><span class="mini"><?= $h($m['subscribed_until']??'No subscription'); ?></span><?php endif; ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section>
